    assign subtractive_axi_bridge_id_ar = (wbm_64b_ar_gnt_subtractive ? wbm_bridge_id_ar : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // wbm 32b path -> wbp
    logic [0:0] wbm_32b_wdest_mem [16];
    logic [4:0] wbm_32b_wdest_wptr, wbm_32b_wdest_rptr;
    wire [0:0] wbm_32b_wdest_enc = 1'd0;
    wire wbm_32b_wdest_push = wbm_32b_awvalid && wbm_32b_awready;
    wire wbm_32b_wdest_pop  = wbm_32b_wvalid && wbm_32b_wready && wbm_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            wbm_32b_wdest_wptr <= '0;
            wbm_32b_wdest_rptr <= '0;
        end else begin
            if (wbm_32b_wdest_push) begin
                wbm_32b_wdest_mem[wbm_32b_wdest_wptr[3:0]] <= wbm_32b_wdest_enc;
